void OpenDDLParser::normalizeBuffer(std::vector<char> &buffer) {
    if (buffer.empty()) {
        return;
    }

    std::vector<char> newBuffer;
    const size_t len(buffer.size());
    char *end(&buffer[len - 1] + 1);
    for (size_t readIdx = 0; readIdx < len; ++readIdx) {
        char *c(&buffer[readIdx]);
        // check for a comment
